 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))

    def edge_bar(r):
        vals = [(c, g[r][c]) for c in range(w) if g[r][c] != bg]
        if not vals:
            return None
        color = vals[0][1]
        cols = [c for c, v in vals if v == color]
        if len(cols) != len(vals) or cols != list(range(min(cols), max(cols) + 1)):
            return None
        return color, min(cols), max(cols)

    top, bottom = edge_bar(0), edge_bar(h - 1)
    if not top or not bottom or top[0] != bottom[0]:
        return g
    bar_color = top[0]
    points = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (bg, bar_color)]
    if len(points) != 1:
        return g
    mr, mc, marker = points[0]

    # The marker selects the matching position in each end bar.
    if top[1] <= mc <= top[2]:
        offset = mc - top[1]
        ctop = mc
        cbottom = bottom[1] + offset
        if cbottom > bottom[2]:
            cbottom = bottom[1] + (offset % (bottom[2] - bottom[1] + 1))
        for r in range(1, mr):
            g[r][ctop] = marker
        g[mr][mc] = 4
        for r in range(h - 2, -1, -1):
            g[r][cbottom] = marker
    elif bottom[1] <= mc <= bottom[2]:
        offset = mc - bottom[1]
        cbottom = mc
        ctop = top[1] + offset
        if ctop > top[2]:
            ctop = top[1] + (offset % (top[2] - top[1] + 1))
        for r in range(h - 2, mr, -1):
            g[r][cbottom] = marker
        g[mr][mc] = 4
        for r in range(1, h):
            g[r][ctop] = marker
    else:
        return g
    return g
